class Battery {
    int capacity;
    Battery(int cap) { this.capacity = cap; }
}
class Phone {
    Battery bat;
    Phone(Battery bat) { this.bat = bat; }
    Phone(Phone p) { this.bat = p.bat; } // Shallow copy
}
public class Main {
    public static void main(String[] args) {
        Phone p1 = new Phone(new Battery(3000));
        Phone p2 = new Phone(p1);
        p2.bat.capacity = 4500;
        System.out.println(p1.bat.capacity + " " + p2.bat.capacity);
    }
}
